"""Plan avant rédaction, chaque section limitée aux preuves lues."""
from pathlib import Path
import json
P=Path(__file__).resolve().parent/'recherche_D65';S={x['key']:x for x in json.loads((P/'sources.json').read_text())['sources']}
def refs(keys):return ' '.join('['+S[k]['id']+']' for k in keys)
sections=[
('Définition : une coagulation qui perd sa localisation','La CIVD est un syndrome acquis secondaire. La définitionISTH2025 réunit activation intravasculaire systémique, fibrinolyse dérégulée et lésion endothéliale. Le microthrombus et la consommation expliquent que thrombose et saignement puissent coexister. D65 comporte D65.0,D65.1,D65.2,D65.9 ; ces catégories ne sont pas quatre stades.',['ISTH25','OFS','CIM']),
('Épidémiologie et contextes à reconnaître','Sepsis, traumatisme, complications obstétricales, tumeurs solides et leucémie promyélocytaire sont des contextes majeurs. Les études de populations et définitions hétérogènes ne donnent pas un taux national suisseD65. Les recherches SuisseCIVD2025/2026,HUG,RMS ont donné références institutionnelles/revues sans incidence nationale spécifique ; lacune conservée.',['REVIEW25','RMS','APL']),
('Physiopathologie du normal à la défaillance','Plaquettes et coagulation circonscrivent normalement une brèche. Le facteur tissulaire, les complexes membranaires, la thrombine et la fibrine sont régulés par antithrombine, protéineC/thrombomoduline et TFPI. L’inflammation étend l’activation et fragilise l’endothélium ; la fibrinolyse peut être insuffisante ou excessive selon le contexte.',['NORMAL-HEMO','REVIEW25','ISTH25']),
('Démarche clinique : trois questions simultanées','Existe-t-il une cause plausible, une hémostase qui se dégrade et une menace d’organe ou un saignement ? Traiter l’urgence et la cause sans attendre un score complet. Le sepsis exige recherche et contrôle du foyer ; obstétrique et APL ont leurs filières urgentes. Aucun schéma antibiotique ou ATRA de mémoire.',['SSC26','APL','REVIEW25','ISTH25']),
('Anamnèse orientée par la chronologie','Rechercher infection, chirurgie/traumatisme, grossesse/postpartum, cancer, médicaments anticoagulants/héparine, transfusion, saignements et résultats antérieurs. L’interrogatoire ne doit pas retarder les gestes urgents ; absence de symptôme n’exclut pas le stade précoce.',['REVIEW25','RMS','ISTH25','HNF']),
('Examen : hémorragie, perfusion et organes','Purpura, ecchymoses, saignement muqueux ou aux ponctions ; cyanose acrale/nécrose, oligurie, hypoxémie, confusion. Aucun signe isolé n’est spécifique. Relier chaque observation au mécanisme, à un examen ciblé et à la réévaluation ; purpura fulminans est une urgence.',['REVIEW25','ISTH25']),
('Syndromes et diagnostics concurrents','Phénotypes thrombotique, hémorragique et mixte sont dynamiques. Distinguer CIVD, microangiopathie thrombotique, hépatopathie sévère, coagulopathie de dilution/perte et complications d’anticoagulants, sans règle simpliste facteurVIII ou rein. Schizocytes non spécifiques ; avis hématologique urgent si microangiopathie.',['REVIEW25','RMS','ISTH25','HNF','FIB']),
('Diagnostic positif : scoreISTH2025 et SIC','ISTHmanifeste≥5 si maladiecompatible ; plaquettes<50G/L2points,50–<1001 ; Ddimer>7LSN3,>3LSN2 ; PT≥6s2,3–<6s1 ; fibrinogène<1g/L1. ScoreSIC≥4 et composantes plaquettes+INR>2 en sepsis ; quatreorganesSOFA. Les seuils stricts, unités, limites d’assay et exemples seront explicités.',['ISTH25','HUG-LAB']),
('Explorations : valeur, tendance et préanalytique','Numération, PTavec témoin, fibrinogèneClauss, Ddimères avecLSN/méthode/unité ; aPTT n’entre pas dansscoremanifeste. Frottis/hémolyse, fonctionrénale/hépatique, lactate et recherchecause orientés. Prélèvementanticoagulé/interférences et transfusion influencent lecture ; normes du laboratoire, pas valeurs universellesinventées.',['HUG-LAB','ISTH25','REVIEW25','TRAUMA']),
('Arbre diagnostique et réévaluation','Menace vitale→circuiturgent/traitementcause+bilans parallèles ; causecompatible→scoreettrajectoire ; atypies→differential/avis ; scorebas→réévaluer, pas exclusion précoce ; amélioration→surveillance de cause,saignement,organes etthrombose.',['ISTH25','REVIEW25','SSC26']),
('Prise en charge : cause, organes, hémostase','Aucun médicament universelCIVD. Substitution si besoinclinique défini ; fibrinogène ne remplacepasplasma/plaquettes. ProphylaxieVTE sepsisdifférented’anticoagulationcurative ; HNF/AT/TXApasautomatiques. FIhaemocomplettanavril2026,Kyberninfev2025,HNFnov2020,TXAsep2026 confrontées auxdirectives contextuelles.',['REVIEW25','SSC26','FIB','AT','HNF','TXA','HUG-TRANS']),
('Prévention, suivi et contextes particuliers','Suivre cause et organes, évolutionhémostatique et effetsproduits ; préventionVTEselonbalanceclinique, sécuritétransfusion/lot. Grossesse,trauma,APL,reinfoie demandentobjectifsspécifiques. Pas dépistageDICpopulationnel ou duréeconduite/Suva inventés.',['SSC26','HUG-TRANS','SWISSMED','PPH-CH','TRAUMA','APL','OFSP','OAMAL']),
('Points clés, paramètres et calculs','Diagnostic1g/Ldistinctdeseuiltrauma≤1,5g/L et objectifsobstétricaux2–2,5. Convertirmg/dLen g/L÷100 ; ratioDdimer résultat/LSNmêmeunité ; PTpatient−témoin ensecondes. Fibrinogène2g à20mg/mL donne100mL et≥20min à5mL/min, exemplearithmétique sansprescription.',['ISTH25','FIB','TRAUMA','PPH-CH']),
('Pièges et examen fédéral','Ne pasconfondre marqueur/syndrome, score/besointhérapeutique,diagnostic/objectif,paralysieduscore/urgence,thromboprophylaxie/traitementDIC. Quatre casfictifs justifiés. PROFILES2017/examen2026 attribués ; lacunesréellesadministratives etépidémiologiques déclarées.',['ISTH25','REVIEW25','SSC26','PROFILES17','MEBEKO26','PROFILES-TRANS'])]
labels=[('Question clinique et enjeu pour l’examen fédéral','✔',['ISTH25','PROFILES17']),('Définition et périmètre CIM-10-GM','✔',['OFS','CIM']),('Classifications et stades','✔ stades précoces/manifestes et phénotypes, pas sous-codes assimilés à stades',['ISTH25']),('Épidémiologie suisse puis européenne','LACUNE incidence/prévalenceD65 nationale non trouvée, recherchesHUG/RMS/Suisse2025–2026 ; populations de revues non transposées',['REVIEW25','RMS']),('Normal → pathologique','✔',['NORMAL-HEMO','REVIEW25']),('Étiologies et facteurs de risque','✔',['REVIEW25','APL']),('Anamnèse et symptômes','✔ ; LACUNE fréquences isolées non trouvées',['REVIEW25']),('Examen clinique','✔ ; LACUNE sensibilités spécifiquesD65 non établies',['REVIEW25']),('Drapeaux rouges et urgences','✔',['REVIEW25','SSC26','APL']),('Examens complémentaires','✔ normes locales et limites',['HUG-LAB','ISTH25']),('Diagnostic différentiel','✔ éléments orientants, pas règle unique exclusive',['REVIEW25','RMS']),('Prise en charge suisse','✔ FI datées et conduite contextuelle',['FIB','HNF','AT','TXA','HUG-TRANS']),('Complications et pronostic','✔ ; pas taux suisse ni risque individuel inventé',['REVIEW25']),('Suivi, prévention, dépistage','✔ suivicontextuel ; pas dépistagepopulationnel proposé',['SSC26','REVIEW25']),('Situations particulières','✔ ; limites pédiatriques explicites',['PPH-CH','TRAUMA','APL','TXA']),('Spécificités suisses','✔ hémovigilance/produits ; LACUNE délaiSuva,conduite et remboursement spécifiqueD65 non trouvés',['SWISSMED','OFSP','OAMAL']),('Critères formels du diagnostic','✔',['ISTH25','OFS']),('Paramètres clés chiffrés','✔ unités et buts séparés',['ISTH25','FIB','TRAUMA','PPH-CH']),('Sous-codes CIM-10-GM couverts','✔ D65.0,D65.1,D65.2,D65.9 expliqués',['OFS','CIM']),('Points d’examen fédéral','✔ objectifs et raisonnement, pas pronostic de sujets',['PROFILES17','MEBEKO26','PROFILES-TRANS'])]
text='# Recherche D65 — Coagulation intravasculaire disséminée\n\nPROMPT_VERITE appliqué ; préparation hors sources canoniques. Lecture ciblée, réemplois attribués, aucune validation médicale humaine.\n\n## Plan monographique en14points\n\n'
for i,(t,b,k) in enumerate(sections,1):text+=f'### {i}. {t}\n\n{b} {refs(k)}\n\n'
text+='## Matrice de complétude\n\n| rubrique | statut | sources |\n|---|---|---|\n'
for t,s,k in labels:text+=f'| {t} | {s} | {refs(k)} |\n'
text+='\n## Sciences, images et limites\n\nSix sous-onglets, sémiologie en premier et neuf unités : normal,signes,mécanismes,examen,interprétation,différentiels,urgence,limites,sources. Anatomie microcirculatoire, histologie du sang, physiologie, biochimie de coagulation et immunologie. Deux originaux réellement affichés : SEMWellcome avec barre10µm et frottisnormal avec barre100µm ; quatre repères français en légende, pixelsintacts. Aucun frottis pathologiqueDIC acquis : liensCommons/Flickr403, ne pas revendiquer lecture visuelle. Schémas causaux nonanatomiques seulement.\n\n## Lacunes et divergences\n\nPas incidence nationaleD65, ni fréquence/sensibilitédes signes, ni délaiSuva/conduiteautomobile spécifique retrouvés. RMS2018 datée, pas prescriptionactuelle ; APC retirée. DGN/guidejaponais non utilisés commeautorisation suisse AT/rhTM. SSC2026 conjointe ESICM/SCCM : page derecommandationspubliques lue, articleabonnement nonlu. BSH2009 404/403 et enquêteISTH2026 éditeur403 nonlues, noncomptées. RMSparacentèse2017 fauxrésultat, exclu. ISTH2025 PDFprimaire obtenu légitimement via sociétéCAHT après403éditeur ; seulessectionsconsignéeslues. Ancienne unité erronée tableau revue2025 et équivoque PT-INR du tableauprimaire expliquées, nonrecopiées. FI TXA profilbiologique comportantcoquilles nonreproduit ; sesrestrictions DIC maintenues. FI FIBobjectif≤limitenormaleinférieure versusobjectifobstétricalsupérieur : divergence explicite, décision spécialisée. FIAT indicationshéréditaires ; aucun raccourci ATbasse→substitution. Les seuilsdiagnostiquesne sontpas objectifsuniversels. Pas posologie enfant/ATRA/antibiotique de mémoire.\n\n## Sources et portée des lectures\n\n'
for x in S.values():text+=f"- [{x['id']}] **{x['titre']}**, {x['version_annee']} ; {x['section_page']}. Fait paraphrasé : {x['passage_paraphrase']}. Limites : {x['limites']}\n"
(P/'recherche.md').write_text(text);(P/'plan.json').write_text(json.dumps({'monographic_plan':[{'point':i,'title':t,'anchor':f'd65-{i}','sources':[S[k]['id'] for k in keys],'coverage':b} for i,(t,b,keys) in enumerate(sections,1)],'matrix20':[{'point':i,'title':t,'status':s,'sources':[S[k]['id'] for k in keys]} for i,(t,s,keys) in enumerate(labels,1)]},ensure_ascii=False,indent=2)+'\n')
